17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	import java.util.Map;
24	import java.util.regex.Pattern;
25	
26	import org.springframework.http.HttpHeaders;
27	import org.springframework.http.HttpStatus;
28	import org.springframework.http.ResponseEntity;
29	import org.springframework.samples.petclinic.mapper.OwnerMapper;
30	import org.springframework.samples.petclinic.mapper.PetMapper;
31	import org.springframework.samples.petclinic.mapper.VisitMapper;
32	import org.springframework.samples.petclinic.model.Owner;
33	import org.springframework.samples.petclinic.model.Pet;
34	import org.springframework.samples.petclinic.model.Visit;
35	import org.springframework.samples.petclinic.rest.api.OwnersApi;
36	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
37	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.PetDto;
39	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
42	import org.springframework.samples.petclinic.service.ClinicService;
43	import org.springframework.security.access.prepost.PreAuthorize;
44	import org.springframework.web.bind.annotation.CrossOrigin;
45	import org.springframework.web.bind.annotation.RequestMapping;
46	import org.springframework.web.bind.annotation.RestController;
47	import org.springframework.web.server.ResponseStatusException;
48	import org.springframework.web.util.UriComponentsBuilder;
49	
50	import jakarta.transaction.Transactional;
51	
52	/**
53	 * @author Vitaliy Fedoriv
54	 */
55	
56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    private final ClinicService clinicService;
62	
63	    private final OwnerMapper ownerMapper;
64	
65	    private final PetMapper petMapper;
66	
67	    private final VisitMapper visitMapper;
68	
69	    public OwnerRestControllerV1(ClinicService clinicService,
70	                                 OwnerMapper ownerMapper,
71	                                 PetMapper petMapper,
72	                                 VisitMapper visitMapper) {
73	        this.clinicService = clinicService;
74	        this.ownerMapper = ownerMapper;
75	        this.petMapper = petMapper;
76	        this.visitMapper = visitMapper;
77	    }
78	
79	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
80	    @Override
81	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
82	        Collection<Owner> owners;
83	        if (lastName != null) {
84	            owners = this.clinicService.findOwnerByLastName(lastName);
85	        } else {
86	            owners = this.clinicService.findAllOwners();
87	        }
88	        if (owners.isEmpty()) {
89	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
90	        }
91	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
92	    }
93	
94	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
95	    @Override
96	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
97	        Owner owner = this.clinicService.findOwnerById(ownerId);
98	        if (owner == null) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
107	        HttpHeaders headers = new HttpHeaders();
108	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
109	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
110	        owner.setTelephone(normalizedTelephone);
111	        owner.setEmail(normalizeEmail(owner.getEmail()));
112	        owner.setAddress(normalizeAddress(owner.getAddress()));
113	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
114	        if (effectiveRegistrationDate == null) {
115	            effectiveRegistrationDate = LocalDate.now();
116	        }
117	        effectiveRegistrationDate = rollToBusinessDay(effectiveRegistrationDate);
118	        owner.setRegistrationDate(effectiveRegistrationDate);
119	        if (countOwnersRegisteredOn(effectiveRegistrationDate) >= DAILY_CREATE_LIMIT) {
120	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
121	                "the maximum number of owners that may be created today has been reached");
122	        }
123	        if (isTelephoneInUse(normalizedTelephone, null)) {
124	            throw new ResponseStatusException(HttpStatus.CONFLICT,
125	                "telephone is already in use by another owner");
126	        }
127	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
128	        if (!sharesHousehold
129	            && this.clinicService.isHouseholdInUse(owner.getLastName(), owner.getAddress(), null)) {
130	            throw new ResponseStatusException(HttpStatus.CONFLICT,
131	                "another owner with the same last name already lives at this address");
132	        }
133	        if (countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
134	            throw new ResponseStatusException(HttpStatus.CONFLICT,
135	                "city has reached its maximum number of owners");
136	        }
137	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
138	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
139	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
140	        if (sharesHousehold) {
141	            this.clinicService.assignHousehold(owner);
142	        }
143	        this.clinicService.saveOwner(owner);
144	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
145	        headers.setLocation(UriComponentsBuilder.newInstance()
146	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
147	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
148	    }
149	
150	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
151	    @Override
152	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
153	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
154	        if (currentOwner == null) {
155	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
156	        }
157	        currentOwner.setAddress(ownerFieldsDto.getAddress());
158	        currentOwner.setCity(ownerFieldsDto.getCity());
159	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
160	        currentOwner.setLastName(ownerFieldsDto.getLastName());
161	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
162	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
163	        this.clinicService.saveOwner(currentOwner);
164	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
165	    }
166	
167	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
168	    @Transactional
169	    @Override
170	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
171	        Owner owner = this.clinicService.findOwnerById(ownerId);
172	        if (owner == null) {
173	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
174	        }
175	        this.clinicService.deleteOwner(owner);
176	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
177	    }
178	
179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Override
181	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
182	        Owner owner = this.clinicService.findOwnerById(ownerId);
183	        if (owner == null) {
184	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
185	        }
186	        HttpHeaders headers = new HttpHeaders();
187	        Pet pet = petMapper.toPet(petFieldsDto);
188	        owner.setId(ownerId);
189	        pet.setOwner(owner);
190	        pet.getType().setName(null);
191	        this.clinicService.savePet(pet);
192	        PetDto petDto = petMapper.toPetDto(pet);
193	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
194	            .buildAndExpand(pet.getId()).toUri());
195	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
196	    }
197	
198	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
199	    @Override
200	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
201	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
202	        if (currentOwner != null) {
203	            Pet currentPet = this.clinicService.findPetById(petId);
204	            if (currentPet != null) {
205	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
206	                currentPet.setName(petFieldsDto.getName());
207	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
208	                this.clinicService.savePet(currentPet);
209	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
210	            }
211	        }
212	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
213	    }
214	
215	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
216	    @Override
217	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
218	        HttpHeaders headers = new HttpHeaders();
219	        Visit visit = visitMapper.toVisit(visitFieldsDto);
220	        Pet pet = new Pet();
221	        pet.setId(petId);
222	        visit.setPet(pet);
223	        this.clinicService.saveVisit(visit);
224	        VisitDto visitDto = visitMapper.toVisitDto(visit);
225	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
226	            .buildAndExpand(visit.getId()).toUri());
227	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
228	    }
229	
230	
231	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
232	    @Override
233	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
234	        Owner owner = this.clinicService.findOwnerById(ownerId);
235	        if (owner != null) {
236	            Pet pet = owner.getPet(petId);
237	            if (pet != null) {
238	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
239	            }
240	        }
241	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
242	    }
243	
244	    /**
245	     * Builds the customer code for a new owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is
246	     * the upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
247	     * last name, and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
248	     * owners that already live in that city (e.g. {@code 'LON-SMI-0007'}).
249	     *
250	     * @param city     the owner's city
251	     * @param lastName the owner's last name
252	     * @return the assigned customer code
253	     */
254	    private String nextCustomerCode(String city, String lastName) {
255	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
256	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
257	        int sequence = countOwnersInCity(city) + 1;
258	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
259	    }
260	
261	    /**
262	     * The maximum number of owners allowed to live in a single city. A create is rejected once the
263	     * owner's city already contains this many owners.
264	     */
265	    private static final int CITY_CAPACITY = 50;
266	
267	    /**
268	     * The maximum number of owners that may be created on a single day. A create is rejected with
269	     * {@link HttpStatus#TOO_MANY_REQUESTS} once this many owners already have today's
270	     * {@code registrationDate}.
271	     */
272	    private static final int DAILY_CREATE_LIMIT = 100;
273	
274	    /**
275	     * Rolls a registration date forward onto a business day: a date that falls on a Saturday or
276	     * Sunday is moved forward to the following Monday, while a date already on a weekday is returned
277	     * unchanged. Applied to the effective registration date (supplied or defaulted to the server
278	     * date) so that the stored {@code registrationDate}, and every value derived from it, always
279	     * falls on a business day.
280	     *
281	     * @param date the effective registration date
282	     * @return the same date when it is a weekday, otherwise the following Monday
283	     */
284	    private static LocalDate rollToBusinessDay(LocalDate date) {
285	        return switch (date.getDayOfWeek()) {
286	            case SATURDAY -> date.plusDays(2);
287	            case SUNDAY -> date.plusDays(1);
288	            default -> date;
289	        };
290	    }
291	
292	    /**
293	     * Counts the existing owners whose {@code registrationDate} equals the given (already
294	     * business-day-adjusted) date, i.e. the number of owners that have already been created for that
295	     * business day. Called before a new owner is saved, so the returned value reflects the number of
296	     * owners created for that day prior to this create.
297	     *
298	     * @param date the adjusted business-day registration date to count against
299	     * @return the number of existing owners registered on that date
300	     */
301	    private int countOwnersRegisteredOn(LocalDate date) {
302	        return (int) this.clinicService.findAllOwners().stream()
303	            .filter(existing -> date.equals(existing.getRegistrationDate()))
304	            .count();
305	    }
306	
307	    /**
308	     * Counts the existing owners that live in the given city, comparing city names case-insensitively.
309	     *
310	     * @param city the city to count owners for
311	     * @return the number of existing owners in that city
312	     */
313	    private int countOwnersInCity(String city) {
314	        return (int) this.clinicService.findAllOwners().stream()
315	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
316	            .count();
317	    }
318	
319	    /**
320	     * Builds the membership number for a new owner, formatted {@code '<customerCode>-M<YY>'} where YY is
321	     * the last two digits of the registration date's year (e.g. {@code 'LON-SMI-0007-M26'}).
322	     *
323	     * @param customerCode     the owner's assigned customer code
324	     * @param registrationDate the owner's registration date
325	     * @return the assigned membership number
326	     */
327	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
328	        String yy = String.format("%02d", registrationDate.getYear() % 100);
329	        return String.format("%s-M%s", customerCode, yy);
330	    }
331	
332	    /**
333	     * Counts the existing owners that already share the given first name and last name, comparing
334	     * both case-insensitively. Called before a new owner is saved, so the returned value reflects
335	     * the number of namesakes that existed prior to this create.
336	     *
337	     * @param firstName the new owner's first name
338	     * @param lastName  the new owner's last name
339	     * @return the number of existing owners with the same first and last name
340	     */
341	    private int countNamesakes(String firstName, String lastName) {
342	        int count = 0;
343	        for (Owner existing : this.clinicService.findAllOwners()) {
344	            if (firstName.equalsIgnoreCase(existing.getFirstName())
345	                && lastName.equalsIgnoreCase(existing.getLastName())) {
346	                count++;
347	            }
348	        }
349	        return count;
350	    }
351	
352	    /**
353	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
354	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
355	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
356	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
357	     * string is what gets stored and returned.
358	     *
359	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
360	     *
361	     * @param telephone the raw telephone value supplied by the client
362	     * @return the normalized E.164 telephone number
363	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
364	     *                                 valid E.164 number (unexpected characters, or not 8 to 15
365	     *                                 digits after the {@code '+'})
366	     */
367	    private static String normalizeTelephone(String telephone) {
368	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
369	        String digits;
370	        if (cleaned.startsWith("+")) {
371	            digits = cleaned.substring(1);
372	        } else {
373	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
374	            digits = "61" + national;
375	        }
376	        if (!digits.matches("[0-9]{8,15}")) {
377	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
378	                "telephone could not be normalized to a valid E.164 number");
379	        }
380	        return "+" + digits;
381	    }
382	
383	    /**
384	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, falling back
385	     * to the raw stored value if it cannot be normalized (e.g. legacy seed data in another format).
386	     *
387	     * @param telephone the stored telephone value, possibly {@code null}
388	     * @return the E.164 form, or the raw value when it cannot be normalized
389	     */
390	    private static String toComparableTelephone(String telephone) {
391	        try {
392	            return normalizeTelephone(telephone);
393	        } catch (ResponseStatusException ex) {
394	            return telephone;
395	        }
396	    }
397	
398	    /**
399	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
400	     * containing at least one dot, none of the three sections containing whitespace or an
401	     * additional {@code @}.
402	     */
403	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
404	
405	    /**
406	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
407	     * (email is optional). When a value is supplied it must be a syntactically valid address; the
408	     * value is then stored and returned lower-cased.
409	     *
410	     * @param email the raw email value supplied by the client, possibly {@code null}
411	     * @return the lower-cased email, or {@code null} when none was supplied
412	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
413	     *                                 is not a syntactically valid address
414	     */
415	    private static String normalizeEmail(String email) {
416	        if (email == null) {
417	            return null;
418	        }
419	        if (!EMAIL_PATTERN.matcher(email).matches()) {
420	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
421	                "email must be a syntactically valid address");
422	        }
423	        return email.toLowerCase(Locale.ROOT);
424	    }
425	
426	    /**
427	     * Common street-type abbreviations expanded to their full word during address normalization.
428	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
429	     */
430	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
431	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
432	
433	    /**
434	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
435	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
436	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
437	     * {@code AVE -> AVENUE}). This normalized value is what gets stored, returned, and used for every
438	     * address comparison (household duplicate detection and the shared household id).
439	     *
440	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
441	     *
442	     * @param address the raw address supplied by the client, possibly {@code null}
443	     * @return the normalized address
444	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
445	     *                                 after normalization (required field)
446	     */
447	    private static String normalizeAddress(String address) {
448	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
449	        if (collapsed.isEmpty()) {
450	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
451	                "address must not be blank");
452	        }
453	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
454	        StringBuilder normalized = new StringBuilder();
455	        for (int i = 0; i < tokens.length; i++) {
456	            if (i > 0) {
457	                normalized.append(' ');
458	            }
459	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
460	        }
461	        return normalized.toString();
462	    }
463	
464	    /**
465	     * Determines whether the given normalized E.164 telephone is already used by any owner other
466	     * than the one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g.
467	     * on create). Stored telephones are compared by their E.164 value so that differently formatted
468	     * inputs representing the same number are treated as duplicates.
469	     *
470	     * @param normalizedTelephone the already-normalized E.164 telephone to look for
471	     * @param excludeId           id of an owner to ignore during the check, or {@code null} for none
472	     * @return {@code true} if another owner already uses the telephone
473	     */
474	    private boolean isTelephoneInUse(String normalizedTelephone, Integer excludeId) {
475	        for (Owner existing : this.clinicService.findAllOwners()) {
476	            if (excludeId != null && excludeId.equals(existing.getId())) {
477	                continue;
478	            }
479	            if (normalizedTelephone.equals(toComparableTelephone(existing.getTelephone()))) {
480	                return true;
481	            }
482	        }
483	        return false;
484	    }
485	
486	}
